syntax:
namespace MyNamespace {  // Original namespace definition; compiler creates a new namespace scope and adds declarations to its symbol table.
    int x;  // Declaration added; in assembly, might be mangled as _ZN10MyNamespace1xE
}

namespace MyNamespace {  // Extension; compiler merges this with the existing namespace, appending declarations without redefining the scope.
    int y;  // Added to the same namespace; mangled similarly, e.g., _ZN10MyNamespace1yE
}

// For unnamed namespaces:
namespace {  // Unnamed namespace; compiler treats this as having internal linkage, mangling symbols uniquely per translation unit.
    int z;  // Internal linkage; not visible outside this TU, e.g., mangled as a unique internal symbol.
}
